add_action( 'woocommerce_before_add_to_cart_form', 'perfectpixel_variable_total_stock' );

function perfectpixel_variable_total_stock() {
	global $product;
	if ( ! $product || ! $product->is_type( 'variable' ) ) {
		return;
	}
	$total = 0;
	foreach ( $product->get_children() as $child_id ) {
		$variation = wc_get_product( $child_id );
		if ( ! $variation || ! $variation->managing_stock() || $variation->get_manage_stock() === 'parent' ) {
			return; // Mixed or parent-level stock: nothing meaningful to sum.
		}
		$total += max( 0, (int) $variation->get_stock_quantity() );
	}
	if ( $total > 0 ) {
		echo '<p class="stock in-stock perfectpixel-total-stock">' . esc_html( str_replace( '{qty}', wc_stock_amount( $total ), '{{total_stock_text}}' ) ) . '</p>';
	}
}
